# Surah At-Tawbah (chapter 9) — part 1: ayat 1-10 (IDs 1236-1245)
SURAH = 9

ENTRIES = {
1236: (
"ایک — بے تعلق — اللہ کی طرف سے — اور اس کے رسولؐ — کی طرف سے — ان — مشرکوں کی طرف — جن سے — تم نے — عہد کیا",
"""۱۔ سورۂ توبہ کا آغاز — ایک تاریخی اعلان سے (بلا بسم اللہ)۔
۲۔ ’’بَرَاءَۃٌ مِّنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ عَاهَدتُّم مِّنَ الْمُشْرِكِينَ‘‘ — ایک — بے تعلق — اللہ کی طرف سے — اور اس کے رسولؐ — کی طرف سے — ان — مشرکوں کی طرف — جن سے — تم نے — عہد کیا — یعنی اللہ اور رسولؐ — مشرکوں سے — عہد — سے — بری ہیں۔
۳۔ عملی سبق: عہد کی قدسیت — اللہ اور رسولؐ کے ساتھ ہے؛ دھوکہ دینے والوں سے — دور رہو۔"""
),
1237: (
"پس — چار ماہ — زمین میں — سیر کرو — اور — جان لو — کہ — تم — اللہ — کو — عاجز — نہیں کر سکتے — اور — یہ کہ اللہ — کافروں کو ذلیل کر دیتا ہے",
"""۱۔ چار ماہ — مشرکوں کو مہلت۔
۲۔ ’’فَسِيحُوا فِي الْأَرْضِ أَرْبَعَۃَ أَشْهُرٍ وَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي اللَّهِ وَأَنَّ اللَّهَ مُخْزِي الْكَافِرِينَ‘‘ — پس — چار ماہ — زمین میں — سیر کرو — اور — جان لو — کہ — تم — اللہ — کو — عاجز — نہیں کر سکتے — اور — یہ کہ اللہ — کافروں کو ذلیل کر دیتا ہے — یعنی مشرکوں کو چار ماہ کی مہلت دی گئی — مگر — اللہ — کو — عاجز کرنا ناممکن ہے۔
۳۔ عملی سبق: مہلت — کی قدر کرو؛ اللہ کی قدرت — سے کوئی بچ نہیں سکتا۔"""
),
1238: (
"اور — ایک اعلان — اللہ اور اس کے رسولؐ کی طرف سے — سب لوگوں کے لیے — بڑے حج کے دن — کہ — اللہ — مشرکوں سے — بری ہے — اور — اس کے رسولؐ بھی — پس — اگر — تم — توبہ کرو — تو یہ — تمہارے لیے — بہتر ہے — اور — اگر — تم — منہ موڑ جاؤ — تو — جان لو — کہ — تم — اللہ — کو — عاجز — نہیں کر سکتے — اور — کافروں کو — دردناک عذاب کی — خوش خبری سنا دو",
"""۱۔ بڑے حج کے دن — اعلانِ براءت۔
۲۔ ’’وَأَذَانٌ مِّنَ اللَّهِ وَرَسُولِهِ إِلَى النَّاسِ يَوْمَ الْحَجِّ الْأَكْبَرِ أَنَّ اللَّهَ بَرِيءٌ مِّنَ الْمُشْرِكِينَ وَرَسُولُهُ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَوَلَّيْتُمْ فَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي اللَّهِ وَبَشِّرِ الَّذِينَ كَفَرُوا بِعَذَابٍ أَلِيمٍ‘‘ — اور — ایک اعلان — اللہ اور اس کے رسولؐ کی طرف سے — سب لوگوں کے لیے — بڑے حج کے دن — کہ — اللہ — مشرکوں سے — بری ہے — اور — اس کے رسولؐ بھی — پس — اگر — تم — توبہ کرو — تو یہ — تمہارے لیے — بہتر ہے — اور — اگر — تم — منہ موڑ جاؤ — تو — جان لو — کہ — تم — اللہ — کو — عاجز — نہیں کر سکتے — اور — کافروں کو — دردناک عذاب کی — خوش خبری سنا دو — یعنی حجِ اکبر کے دن — اللہ نے — واضح اعلان کیا — مشرکوں سے — اظہار براءت — اور توبہ کا موقع۔
۳۔ عملی سبق: توبہ — کبھی دیر سے — نہیں ہوتی؛ فوراً اپنا راستہ درست کرو۔"""
),
1239: (
"سوائے ان — مشرکوں کے — جن سے — تم نے — عہد کیا — پھر — انہوں نے تمہیں — کسی چیز — میں — کمی نہیں کی — اور — نہ — کسی کے خلاف — تمہارا ساتھ دیا — تو — ان — کا — عہد — ان کے میعاد — تک — پورا کرو — بے شک — اللہ — متقیوں سے — محبت کرتا ہے",
"""۱۔ عہد — جن مشرکوں نے پورا کیا — پورا کرنا ضروری ہے۔
۲۔ ’’إِلَّا الَّذِينَ عَاهَدتُّم مِّنَ الْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْئًا وَلَمْ يُظَاهِرُوا عَلَيْكُمْ أَحَدًا فَأَتِمُّوا إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُتَّقِينَ‘‘ — سوائے ان — مشرکوں کے — جن سے — تم نے — عہد کیا — پھر — انہوں نے تمہیں — کسی چیز — میں — کمی نہیں کی — اور — نہ — کسی کے خلاف — تمہارا ساتھ دیا — تو — ان — کا — عہد — ان کے میعاد — تک — پورا کرو — بے شک — اللہ — متقیوں سے — محبت کرتا ہے — یعنی جو مشرک — عہد توڑیں نہیں — ان کا عہد — پورا کرو۔
۳۔ عملی سبق: آپ — اپنے عہد پر — قائم رہو؛ اللہ — متقیوں سے — محبت کرتا ہے۔"""
),
1240: (
"پس — جب — حرام ماہ ختم ہو جائیں — تو — مشرکوں کو — جہاں — بھی — پاؤ — قتل کرو — اور — انہیں پکڑو — اور — ان کو گھیرو — اور — ان — کے لیے — ہر گھات — میں — بیٹھو — پس — اگر — وہ — توبہ کریں — اور نماز قائم کریں — اور زکوٰۃ دیں — تو — انہیں — جانے دو — بے شک — اللہ — بخشنے والا مہربان ہے",
"""۱۔ حرام ماہ — ختم ہونے کے بعد — جنگی احکام۔
۲۔ ’’فَإِذَا انسَلَخَ الْأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ فَإِن تَابُوا وَأَقَامُوا الصَّلَاۃَ وَآتَوُا الزَّكَاۃَ فَخَلُّوا سَبِيلَهُمْ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ‘‘ — پس — جب — حرام ماہ ختم ہو جائیں — تو — مشرکوں کو — جہاں — بھی — پاؤ — قتل کرو — اور — انہیں پکڑو — اور — ان کو گھیرو — اور — ان — کے لیے — ہر گھات — میں — بیٹھو — پس — اگر — وہ — توبہ کریں — اور نماز قائم کریں — اور زکوٰۃ دیں — تو — انہیں — جانے دو — بے شک — اللہ — بخشنے والا مہربان ہے — یعنی حرام ماہ کے بعد — جنگی احکام لاگو ہوتے ہیں — مگر — توبہ — کا راستہ — کھلا ہے۔
۳۔ عملی سبق: توبہ — ہمیشہ — بچاؤ کا راستہ ہے۔"""
),
1241: (
"اور — اگر — مشرکوں میں سے — کوئی — تجھ سے — پناہ مانگی — تو — اسے — پناہ دو — یہاں تک کہ — وہ — اللہ کا کلام — سن لے — پھر — اسے — اس کے — امن کی جگہ — پہنچا دو — یہ — اس لیے کہ وہ — ایسی قوم ہیں جو — نہیں جانتے",
"""۱۔ مشرک جو پناہ مانگیں — کلامِ الٰہی سنانے تک — پناہ ملتی ہے۔
۲۔ ’’وَإِنْ أَحَدٌ مِّنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَامَ اللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ‘‘ — اور — اگر — مشرکوں میں سے — کوئی — تجھ سے — پناہ مانگی — تو — اسے — پناہ دو — یہاں تک کہ — وہ — اللہ کا کلام — سن لے — پھر — اسے — اس کے — امن کی جگہ — پہنچا دو — یہ — اس لیے کہ وہ — ایسی قوم ہیں جو — نہیں جانتے — یعنی مشرک جو — پناہ مانگیں — انہیں — قرآن سننے تک — حفاظت — دی جائے — پھر — محفوظ جگہ تک — پہنچایا جائے۔
۳۔ عملی سبق: ہدایت کا پیغام پہنچانا — سب کا فرض ہے۔"""
),
1242: (
"مشرکوں کا — اللہ اور اس کے رسولؐ — کے ہاں — کوئی عہد — نہیں — سوائے ان کے جن سے — تم نے — مسجد الحرام کے پاس — عہد کیا — پس — جب تک — وہ — تمہارے ساتھ — سیدھے رہیں — تم بھی ان کے ساتھ — سیدھے رہو — بے شک — اللہ — متقیوں — سے — محبت کرتا ہے",
"""۱۔ مسجد الحرام کے پاس — عہد — مکمل کرنے کا حکم۔
۲۔ ’’كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ اللَّهِ وَعِندَ رَسُولِهِ إِلَّا الَّذِينَ عَاهَدتُّمْ عِندَ الْمَسْجِدِ الْحَرَامِ فَمَا اسْتَقَامُوا لَكُمْ فَاسْتَقِيمُوا لَهُمْ إِنَّ اللَّهَ يُحِبُّ الْمُتَّقِينَ‘‘ — مشرکوں کا — اللہ اور اس کے رسولؐ — کے ہاں — کوئی عہد — نہیں — سوائے ان کے جن سے — تم نے — مسجد الحرام کے پاس — عہد کیا — پس — جب تک — وہ — تمہارے ساتھ — سیدھے رہیں — تم بھی ان کے ساتھ — سیدھے رہو — بے شک — اللہ — متقیوں — سے — محبت کرتا ہے — یعنی مسجد الحرام کے عہد کو — پورا کرو — جیسے — وہ — سیدھے رہیں۔
۳۔ عملی سبق: وعدے — سیدھے دل سے — پورے کرو؛ اللہ — متقیوں سے — محبت کرتا ہے۔"""
),
1243: (
"کیسے — ہو — سکتا ہے (ان کا عہد) — جب — کہ — وہ — اگر — تم پر — غالب آ جائیں — تو — تمہارے ساتھ — نہ قرابت داری کا لحاظ رکھیں — اور — نہ — عہد کا — وہ — تمہیں — اپنی زبانی باتوں سے — مطمئن کرتے ہیں — اور ان کے — دل — انکار کرتے ہیں — اور — ان — میں سے اکثر — فاسق ہیں",
"""۱۔ مشرکوں کا کردار — قرابت اور عہد — کی پرواہ نہ کرنا۔
۲۔ ’’كَيْفَ وَإِن يَظْهَرُوا عَلَيْكُمْ لَا يَرْقُبُوا فِيكُمْ إِلًّا وَلَا ذِمَّۃً يُرْضُونَكُم بِأَفْوَاهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَاسِقُونَ‘‘ — کیسے — ہو — سکتا ہے (ان کا عہد) — جب — کہ — وہ — اگر — تم پر — غالب آ جائیں — تو — تمہارے ساتھ — نہ قرابت داری کا لحاظ رکھیں — اور — نہ — عہد کا — وہ — تمہیں — اپنی زبانی باتوں سے — مطمئن کرتے ہیں — اور ان کے — دل — انکار کرتے ہیں — اور — ان — میں سے اکثر — فاسق ہیں — یعنی مشرک — غالب آ جائیں تو — نہ — قرابت — نہ — عہد — کی پرواہ کرتے ہیں — زبانی مصلحت — صرف — منافقت ہے۔
۳۔ عملی سبق: زبانی وعدے — دلوں کو نہیں ظاہر کرتے؛ عبرت حاصل کرو۔"""
),
1244: (
"انہوں نے — اللہ کی آیات — کو — تھوڑی قیمت پر — فروخت کیا — اور — اس کے راستے سے — روکا — بے شک — ان — کا کیا ہوا — بہت برا ہے",
"""۱۔ مشرک — آیاتِ اللہ — بیچنے والے — دین کے دشمن۔
۲۔ ’’اشْتَرَوْا بِآيَاتِ اللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا عَن سَبِيلِهِ إِنَّهُمْ سَاءَ مَا كَانُوا يَعْمَلُونَ‘‘ — انہوں نے — اللہ کی آیات — کو — تھوڑی قیمت پر — فروخت کیا — اور — اس کے راستے سے — روکا — بے شک — ان — کا کیا ہوا — بہت برا ہے — یعنی مشرک — دین کو دنیا کے بدلے — بیچ دیتے ہیں — اور — اللہ کی راہ سے — روکتے ہیں۔
۳۔ عملی سبق: دین کو — کبھی دنیا کے بدلے — نہ بیچو؛ یہ — سب سے بڑا جرم ہے۔"""
),
1245: (
"وہ — مؤمن کے ساتھ — نہ قرابت داری — کا لحاظ رکھتے ہیں — اور — نہ — عہد کا — اور یہی لوگ — سرکش ہیں",
"""۱۔ مشرک — سبھی — سرکش۔
۲۔ ’’لَا يَرْقُبُونَ فِي مُؤْمِنٍ إِلًّا وَلَا ذِمَّۃً وَأُولَٰئِكَ هُمُ الْمُعْتَدُونَ‘‘ — وہ — مؤمن کے ساتھ — نہ قرابت داری — کا لحاظ رکھتے ہیں — اور — نہ — عہد کا — اور یہی لوگ — سرکش ہیں — یعنی مشرک — مؤمنوں کے بارے میں — نہ قرابت — نہ عہد — کی کوئی پرواہ کرتے ہیں — یہی — سرکشی ہے۔
۳۔ عملی سبق: مؤمن کی احترام — سب کے لیے لازم ہے۔"""
),
}
